        .room-card { display: flex; align-items: center; justify-content: space-between; padding: 15px; margin: 10px 0; border: 1px solid #ddd; border-radius: 8px; background: #fafafa; }
        .available { border-left: 5px solid #27ae60; }
        .booked { border-left: 5px solid #e74c3c; }
        button { cursor: pointer; padding: 8px 15px; border: none; border-radius: 4px; background: #3498db; color: white; font-weight: bold; }
        button:disabled { background: #ccc; }
        .status-msg { margin-top: 15px; padding: 10px; border-radius: 4px; font-size: 0.9em; }
    </style>
</head>
<body>
    <div class="container">
        <h1>회의실 예약 현황</h1>
        <div id="room-list"></div>
        <div id="msg" class="status-msg"></div>
    </div>

    <script>
        const rooms = [
            { id: 1, name: "대회의실 (10인)", status: "available" },
            { id: 2, name: "소회의실 A (4인)", status: "booked" },
            { id: 3, name: "소회의실 B (4인)", status: "available" }
        ];

        function render() {
            const container = document.getElementById('room-list');
            container.innerHTML = rooms.map(room => `
                <div class="room-card ${room.status}">
                    <div>
                        <strong>${room.name}</strong><br>
                        <small>현재 상태: ${room.status === 'available' ? '예약 가능' : '사용 중'}</small>
                    </div>
                    <button onclick="toggleRoom(${room.id})" ${room.status === 'booked' ? 'disabled' : ''}>
                        ${room.status === 'available' ? '예약하기' : '예약됨'}
                    </button>
                </div>
            `).join('');
        }

        function toggleRoom(id) {
            const room = rooms.find(r => r.id === id);
            if (room.status === 'available') {
                room.status = 'booked';
                document.getElementById('msg').innerText = `${room.name}이(가) 성공적으로 예약되었습니다.`;
                document.getElementById('msg').style.backgroundColor = '#d4edda';
            }
            render();
        }

        render();
    </script>
</body>
</html>
