        </div>
        <ul id="studentList" class="list"></ul>
        <div id="msg"></div>
    </div>

    <script>
        let students = [
            { id: 1, name: "김철수", present: true },
            { id: 2, name: "이영희", present: false }
        ];

        function render() {
            const list = document.getElementById('studentList');
            list.innerHTML = '';
            students.forEach((s, index) => {
                const li = document.createElement('li');
                li.className = 'item';
                li.innerHTML = `
                    <span>${s.name}</span>
                    <span class="status ${s.present ? 'present' : 'absent'}" onclick="toggleStatus(${index})">
                        ${s.present ? '출석' : '결석'}
                    </span>
                `;
                list.appendChild(li);
            });
        }

        function addStudent() {
            const input = document.getElementById('nameInput');
            if (input.value.trim() === '') return;
            students.push({ id: Date.now(), name: input.value, present: false });
            document.getElementById('msg').innerText = `'${input.value}'님이 명단에 추가되었습니다.`;
            input.value = '';
            render();
        }

        function toggleStatus(index) {
            students[index].present = !students[index].present;
            render();
        }

        render();
    </script>
</body>
