        <button onclick="addMenu()">추가</button>
    </div>
    <ul id="menuList" class="menu-list">
        <li class="menu-item">김치찌개</li>
        <li class="menu-item">돈가스</li>
        <li class="menu-item">샐러드</li>
    </ul>
    <button class="spin-btn" onclick="spin()">오늘의 메뉴 뽑기!</button>
    <div id="result"></div>
</div>

<script>
    function addMenu() {
        const input = document.getElementById('menuInput');
        if (!input.value) return;
        const li = document.createElement('li');
        li.className = 'menu-item';
        li.textContent = input.value;
        document.getElementById('menuList').appendChild(li);
        input.value = '';
    }

    function spin() {
        const items = Array.from(document.querySelectorAll('.menu-item')).map(el => el.textContent);
        const res = document.getElementById('result');
        if (items.length === 0) return;

        let count = 0;
        const interval = setInterval(() => {
            res.textContent = items[Math.floor(Math.random() * items.length)];
            count++;
            if (count > 10) clearInterval(interval);
        }, 100);
    }
</script>
</body>
</html>
